import numpy as np

def boundary_clamping(positions, bounds):
    """Clamp positions to bounds"""
    lower, upper = bounds
    return np.clip(positions, lower, upper)


def boundary_reflecting(positions, velocities, bounds):
    """Reflect particles off boundaries and reverse velocity"""
    lower, upper = bounds
    positions_copy = positions.copy()
    velocities_copy = velocities.copy()
    
    for d in range(positions.shape[1]):
        below = positions_copy[:, d] < lower
        above = positions_copy[:, d] > upper
        positions_copy[below, d] = lower - (positions_copy[below, d] - lower)
        positions_copy[above, d] = upper - (positions_copy[above, d] - upper)
        velocities_copy[below, d] = -velocities_copy[below, d]
        velocities_copy[above, d] = -velocities_copy[above, d]
    
    return positions_copy


def boundary_wraparound(positions, bounds):
    """Wrap positions to opposite boundary (toroidal)"""
    lower, upper = bounds
    range_val = upper - lower
    positions_copy = positions.copy()
    
    for d in range(positions.shape[1]):
        positions_copy[:, d] = lower + np.mod(positions_copy[:, d] - lower, range_val)
    
    return positions_copy


def boundary_random_reset(positions, bounds):
    """Randomly reset out-of-bounds positions"""
    lower, upper = bounds
    positions_copy = positions.copy()
    
    for d in range(positions.shape[1]):
        out_of_bounds = (positions_copy[:, d] < lower) | (positions_copy[:, d] > upper)
        positions_copy[out_of_bounds, d] = np.random.uniform(lower, upper, np.sum(out_of_bounds))
    
    return positions_copy


def boundary_velocity_damping(positions, velocities, bounds, damping=0.5):
    """Reverse velocity with damping on boundary crossing"""
    lower, upper = bounds
    positions_copy = positions.copy()
    velocities_copy = velocities.copy()
    
    for d in range(positions.shape[1]):
        below = positions_copy[:, d] < lower
        above = positions_copy[:, d] > upper
        positions_copy[below, d] = lower
        positions_copy[above, d] = upper
        velocities_copy[below, d] = -velocities_copy[below, d] * damping
        velocities_copy[above, d] = -velocities_copy[above, d] * damping
    
    return positions_copy
